const input = Array.isArray($json) ? $json : [$json];
const lostReasonEnum = ['price', 'timing', 'competitor', 'no-response', 'scope'];
return input.map((deal) => {
  const quoteAgeDays = Number(deal.quoteAgeDays ?? 0);
  const value = Number(deal.estimateValue ?? 0);
  const cadence = quoteAgeDays >= 14 ? 'manager-review' : quoteAgeDays >= 5 ? 'follow-up-now' : 'wait';
  const messageTheme = value >= 10000 ? 'replacement-value-and-comfort' : 'repair-scope-and-schedule';
  const taggedReason = `${deal.lostReason ?? ''}`.toLowerCase();
  const lostReason = lostReasonEnum.includes(taggedReason) ? taggedReason : (quoteAgeDays >= 14 ? 'no-response' : null);
  const financeReminderEligible = value >= 7500;
  return { json: { ...deal, cadence, messageTheme, lostReason, financeReminderEligible, nextAction: cadence === 'wait' ? 'No message today.' : 'Send approved estimate follow-up.' } };
});
